/**
 * The per-gate report (`reports/gates.md`): every recorded run, case by case, with gate 1 (knowledge), gate 2
 * (organisation) and gate 3 (layout) reported separately, and the hand-written references as the baseline that shows
 * what the checks can decide today. Generated by `UPDATE_GOLDEN=1 npm run test:golden`; never edited by hand.
 */
import type { AssertionResult } from "./evaluate";
import { describeFatalShare, ROBUSTNESS_SEED, ROBUSTNESS_SHUFFLES, type Robustness } from "./frameOrder";
import type { RecordingReplay, Verdict } from "./replay";

export interface ReferenceRow {
  caseId: string;
  /** Rendered with organisation v1 (today's rules). */
  results: AssertionResult[];
  verdict: Verdict;
  /**
   * The same reference rendered with organisation v2 (distil mode: frame order, sub-groups, frame splitting), for the
   * gate 3 column: a render assertion scoped to `"organisation": "v2"` is decided only here.
   */
  v2?: { results: AssertionResult[]; verdict: Verdict };
}

/** Frame order robustness of one reference (report only): today's organisation rules and v2's. */
export interface RobustnessRow {
  caseId: string;
  v1: Robustness;
  v2: Robustness;
}

const GATE_NAMES = { 1: "Gate 1 knowledge", 2: "Gate 2 organisation", 3: "Gate 3 layout" } as const;

function table(head: string[], rows: (string | number)[][]): string {
  return [`| ${head.join(" | ")} |`, `|${head.map(() => "---").join("|")}|`, ...rows.map((r) => `| ${r.join(" | ")} |`)].join("\n");
}

/** "PASS 40/43, 3 undecided" or "FAIL 38/43 (2 critical), 3 undecided". */
function gateCell(results: readonly AssertionResult[], gate: 1 | 2 | 3, v: Verdict): string {
  const mine = results.filter((r) => r.gate === gate);
  const decided = mine.filter((r) => r.status === "pass" || r.status === "fail");
  const passed = decided.filter((r) => r.status === "pass").length;
  const g = v.gates.find((x) => x.gate === gate)!;
  const undecided = mine.length - decided.length;
  const head = `${g.pass ? "PASS" : "FAIL"} ${passed}/${decided.length}${g.failedCritical.length ? ` (${g.failedCritical.length} critical)` : ""}`;
  return undecided ? `${head}, ${undecided} undecided` : head;
}

/** How many undecided results, by why: never counted as passed. */
function undecidedBreakdown(results: readonly AssertionResult[]): string {
  const n = (s: AssertionResult["status"]) => results.filter((r) => r.status === s).length;
  return `${n("needs_judgement")} need judgement, ${n("not_evaluable")} not evaluable, ${n("no_input")} without input`;
}

const failures = (results: readonly AssertionResult[]) => results.filter((r) => r.status === "fail");
const escape = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");

function recordingSection(r: RecordingReplay): string[] {
  const m = r.meta;
  const out: string[] = [`### ${m.runId} (${m.gate ? "gating" : "report only"})`, ""];
  out.push(`Recorded ${m.recordedAt}, approved by ${m.approvedBy}. ${m.provider} · ${m.model} · noteModel \`${m.pipeline.noteModel}\` · prompt ${m.pipeline.promptVersion} · app ${m.pipeline.appVersion}.`, "");
  if (r.issues.length) out.push("**Recording issues:**", "", ...r.issues.map((i) => `- ${escape(i)}`), "");
  out.push(
    table(
      ["Case", "Attempt", GATE_NAMES[1], GATE_NAMES[2], GATE_NAMES[3], "Inputs"],
      r.cases.map((c) => [
        c.caseId,
        c.attempt,
        gateCell(c.results, 1, c.verdict),
        gateCell(c.results, 2, c.verdict),
        gateCell(c.results, 3, c.verdict),
        [c.inputs.plan ? "plan" : "no plan", c.inputs.lens !== "none" ? `lens (${c.inputs.lens})` : "", c.inputs.reconcile !== "none" ? `reconcile (${c.inputs.reconcile})` : "", c.inputs.run ? "run output" : "no run output"].filter(Boolean).join(", "),
      ]),
    ),
    "",
  );
  for (const c of r.cases) {
    const failed = failures(c.results);
    const notes = [...(c.note ? [`Note: ${c.note}`] : []), ...(c.planLosses.length ? [`validateVisualPlan dropped: ${c.planLosses.join("; ")}`] : [])];
    if (!failed.length && !notes.length) continue;
    out.push(`**${c.caseId} #${c.attempt}**`, "");
    for (const n of notes) out.push(`- ${escape(n)}`);
    for (const f of failed) out.push(`- gate ${f.gate}, ${f.severity}: \`${f.id}\`: ${escape(f.detail)}`);
    out.push("");
  }
  return out;
}

function robustnessSection(rows: readonly RobustnessRow[]): string[] {
  const out: string[] = ["## Frame order robustness (report only)", ""];
  out.push(
    `Each reference re-rendered with its frames in ${ROBUSTNESS_SHUFFLES} other orders (group nodes shuffled in place, seed ${ROBUSTNESS_SEED}), as a real run's outline might order them: how many orders give a fatal layout issue (a link through a card), and the median link crossings. Organisation v1 is today's layout; v2 orders frames by their links (organisation-layout plan §3.3). Cases whose links all stay inside frames have nothing to measure (–). Never gating.`,
    "",
  );
  out.push(
    table(
      ["Case", "Frames", "Links across frames", "v1: orders with a fatal issue", "v1: median crossings", "v2: orders with a fatal issue", "v2: median crossings"],
      rows.map((r) => [r.caseId, r.v1.frames, r.v1.crossLinks, describeFatalShare(r.v1), r.v1.orders ? r.v1.medianCrossings : "–", describeFatalShare(r.v2), r.v2.orders ? r.v2.medianCrossings : "–"]),
    ),
    "",
  );
  return out;
}

export function buildGateReport(references: readonly ReferenceRow[], recordings: readonly RecordingReplay[], robustness: readonly RobustnessRow[] = []): string {
  const out: string[] = ["# Per-gate report", ""];
  out.push("Generated by `UPDATE_GOLDEN=1 npm run test:golden`. Do not edit by hand.", "");
  out.push(
    "Each gate is reported on its own: gate 1 knowledge (source fidelity, coverage, traceability), gate 2 organisation (grouping, element selection, relationships, architecture and Lens), gate 3 layout (the product's renderer). `PASS a/b` counts decided deterministic assertions; a gate fails only on a critical failure. Undecided assertions (judged, `future`, or without input) are never counted as passed.",
    "",
  );

  out.push("## Recorded runs", "");
  if (!recordings.length) out.push("None. No live run has been approved and recorded yet (`recordings/README.md`).", "");
  for (const r of recordings) out.push(...recordingSection(r));

  out.push("## Baseline: the hand-written reference outputs", "");
  const v2 = references.some((r) => r.v2);
  out.push(
    `What a good output scores today. Every reference must pass every gate (\`dataset.test.ts\`); the undecided column is what the checks can't settle without a judge or a run's own output (citations, accounting).${v2 ? " Gate 3 is shown for both organisation rules: v1 (today's layout, which every other column uses) and v2 (distil mode); an assertion scoped to the other rules counts as undecided (not evaluable) in each." : ""}`,
    "",
  );
  out.push(
    table(
      ["Case", GATE_NAMES[1], GATE_NAMES[2], v2 ? `${GATE_NAMES[3]} (v1)` : GATE_NAMES[3], ...(v2 ? [`${GATE_NAMES[3]} (v2)`] : []), "Undecided"],
      references.map((r) => [
        r.caseId,
        gateCell(r.results, 1, r.verdict),
        gateCell(r.results, 2, r.verdict),
        gateCell(r.results, 3, r.verdict),
        ...(v2 ? [r.v2 ? gateCell(r.v2.results, 3, r.v2.verdict) : "–"] : []),
        undecidedBreakdown(r.results),
      ]),
    ),
    "",
  );
  if (robustness.length) out.push(...robustnessSection(robustness));
  return `${out.join("\n")}\n`;
}
